import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { replyToCommentHandler } from "../handlers/replyToCommentHandler";
import type { ApiError } from "../runtime/client";
import type { FeedPartition } from "../types/FeedPartition";
import type { PostCommentEntityType } from "../types/PostCommentEntityType";
import type { ReplyToPostCommentRequest } from "../types/ReplyToPostCommentRequest";

type Data = Awaited<ReturnType<typeof replyToCommentHandler>>;
type Vars = { postId: FeedPartition; commentId: PostCommentEntityType; req: ReplyToPostCommentRequest };

export function useReplyToComment(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => replyToCommentHandler(vars.postId, vars.commentId, vars.req),
    ...options,
  });
}
